-- PT118-S4-Q3. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT118-S4-Q3$batch10$ AND q.stimulus=$batch10$Nylon industry spokesperson: Even though cotton and nylon are used for similar purposes, some people have the mistaken notion that cotton is natural but nylon is not. However, nylon’s main components come from petroleum and from the nitrogen in the atmosphere. Clearly the atmosphere is natural. And petroleum comes from oil, which in turn comes from ancient plants—a natural source.$batch10$ AND q.prompt=$batch10$Which one of the following principles, if valid, most helps to justify the nylon industry spokesperson's reasoning?$batch10$ AND q.correct_choice=$batch10$E$batch10$) THEN RAISE EXCEPTION 'Question changed: PT118-S4-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT118-S4-Q3$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S4-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT118-S4-Q3$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$It's a mistake to think nylon is not natural.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$Nylon's main components come from petroleum and from nitrogen in the atmosphere. The atmosphere is natural, and petroleum comes from ancient plants, a natural source.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The spokesperson traces each main component back to a natural origin and concludes nylon is natural. The principle has to say that natural origins for the main components make a substance natural.$batch10$), (3, $batch10$Goal$batch10$, $batch10$If a substance's main components have natural origins, the substance is natural.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT118-S4-Q3$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$The spokesperson never discusses what nylon is used for. The argument is about where its components come from.$batch10$), ($batch10$B$batch10$, $batch10$This is about production processes. The spokesperson talks only about the sources of the components.$batch10$), ($batch10$C$batch10$, $batch10$This caps a substance's naturalness at its least natural component. It could only show that nylon is no more natural than petroleum. It never says when something counts as natural.$batch10$), ($batch10$D$batch10$, $batch10$This is about one substance being more natural than another. The spokesperson isn't saying nylon is more natural than cotton, only that it is natural.$batch10$), ($batch10$E$batch10$, $batch10$Nylon's main components come from the atmosphere and from petroleum, and both have natural origins. This principle says that makes nylon natural.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT118-S4-Q3$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
